import { useEffect, useRef, useState } from 'react'
import type { Direction } from './DirectionDisplay'
import { useI18n } from '../../../../i18n'

/** Generated by `scripts/generate-audio.mjs` as `<language>/<word>/<variation>.wav`. */
const files = import.meta.glob<string>('/assets/audio/*/*/*.wav', { eager: true, query: '?url', import: 'default' })

/** Variations by `<language>/<word>`. */
const variations: Record<string, string[]> = {}
for (const [path, url] of Object.entries(files)) {
  const [, , , language, word] = path.split('/')
  ;(variations[`${language}/${word}`] ??= []).push(url)
}

/** Same spelling the audio script uses for folder names: no accents, lowercase. */
const slug = (text: string) =>
  text
    .normalize('NFKD')
    .replace(/[^\x00-\x7f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')

/** A random recording of the direction word in the language (`pt-br` finds `pt`), else the English one. */
function pickRecording(direction: Direction, language: string, word: string): string | undefined {
  const options =
    variations[`${language}/${slug(word)}`] ??
    variations[`${language.split('-')[0]}/${slug(word)}`] ??
    variations[`en/${direction}`]
  return options?.[Math.floor(Math.random() * options.length)]
}

/** Time to answer after the first playback: the user may spend part of it on replays. */
export const AUDIO_TIMEOUT_SECONDS = 8

type Props = {
  direction: Direction
  /** called once the first playback is over */
  onDirectionSet: (direction: Direction) => void
}

/**
 * Says "left" or "right" out loud, in the active language, with a random voice. Starts by itself and can
 * be played again as often as wanted; if the browser blocks the autoplay, pressing the button is the first play.
 * Remount (change `key`) for a new round.
 */
export default function AudioDisplay({ direction, onDirectionSet }: Props) {
  const { t, language } = useI18n()
  const [src] = useState(() => pickRecording(direction, language, t(`direction.${direction}`)))
  const audio = useRef<HTMLAudioElement | null>(null)
  const [plays, setPlays] = useState(0)
  const [playing, setPlaying] = useState(false)
  const onSet = useRef(() => onDirectionSet(direction))
  onSet.current = () => onDirectionSet(direction)
  const announced = useRef(false)
  // the growing ring is moved straight on the element every frame, not through React state
  const ring = useRef<SVGCircleElement>(null)

  useEffect(() => {
    if (!src) {
      // nothing to play: don't leave the round waiting
      onSet.current()
      return
    }
    const a = new Audio(src)
    audio.current = a
    let frame = 0
    const showProgress = (fraction: number) => ring.current?.setAttribute('stroke-dashoffset', String(1 - fraction))
    // timed from the moment playback starts rather than read from `currentTime`, which can still hold the previous position (or jump) for the first frames
    let startedAt = 0
    const tick = () => {
      const length = Number.isFinite(a.duration) ? a.duration * 1000 : 0
      showProgress(length > 0 ? Math.min((performance.now() - startedAt) / length, 1) : 0)
      frame = requestAnimationFrame(tick)
    }
    a.onplaying = () => {
      setPlays((n) => n + 1)
      setPlaying(true)
      cancelAnimationFrame(frame)
      startedAt = performance.now()
      showProgress(0)
      tick()
    }
    const stop = () => {
      cancelAnimationFrame(frame)
      showProgress(0)
      setPlaying(false)
      if (announced.current) return
      announced.current = true
      onSet.current()
    }
    a.onended = stop
    a.onerror = stop
    a.play().catch(() => {})
    return () => {
      cancelAnimationFrame(frame)
      a.onplaying = a.onended = a.onerror = null
      a.pause()
    }
  }, [src])

  const play = () => {
    const a = audio.current
    if (!a) return
    a.currentTime = 0
    a.play().catch(() => {})
  }

  const canPlay = !!src && !playing
  return (
    <button
      type="button"
      onClick={play}
      disabled={!canPlay}
      aria-label={plays === 0 ? t('audio.play') : t('audio.replay')}
      className="relative flex size-40 cursor-pointer items-center justify-center text-ink transition active:scale-95 disabled:cursor-default"
    >
      <svg viewBox="0 0 100 100" aria-hidden className="absolute inset-0 size-full -rotate-90" fill="none">
        <circle cx="50" cy="50" r="45" strokeWidth="3" className="stroke-gray-mid" />
        {/* thicker ring on top of the outline; pathLength 1 lets the offset be the fraction left to draw */}
        <circle ref={ring} cx="50" cy="50" r="45" strokeWidth="8" pathLength="1" strokeDasharray="1" strokeDashoffset="1" className="stroke-gray-mid" />
      </svg>
      <svg viewBox="0 0 24 24" aria-hidden className="relative size-16" fill="currentColor">
        <path d="M3 9v6h4l5 4V5L7 9H3z" />
        {playing && <path d="M15.5 8.5a5 5 0 0 1 0 7M18 6a8.5 8.5 0 0 1 0 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />}
      </svg>
    </button>
  )
}
